type AnalyticsTrackType = {
  event: string;
  event_category: string;
  event_action: string;
  event_label: string;
  userUid: string;
  additionalProps?: { [key: string]: string };
};

export const useAnalyticsTrack = () => {
  const trackEvent = ({ event, event_category, event_action, event_label, userUid, additionalProps }: AnalyticsTrackType) => {

    if (window.dataLayer) {
      window.dataLayer.push({
        event,
        event_category,
        event_action,
        event_label,
        userUid,
        ...additionalProps,
      });
    } else {
      console.warn('GTM not initialized');
    }
  };

  return trackEvent;
};
